#[test]
fn numeric_symbolic_verbose_rule_forms_and_round_trips() {
    let mut e = Engine::default();
    run(&mut e, TIPP);
    run(
        &mut e,
        "a=addRule(f,[1 1 1 1 2;2 0 2 0.5 1;3 -2 3 0.75 1]);b=addRule(f,{'service==poor | food==rancid => tip=cheap (1)','service==good => tip=average (0.5)','service==excellent & food~=delicious => tip=generous (0.75)'});",
    );
    run(
        &mut e,
        "c=addRule(f,[\"If service is poor or food is rancid then tip is cheap (1)\",\"If service is good then tip is average (0.5)\",\"If service is excellent and food is not delicious then tip is generous (0.75)\"]);",
    );
    check(
        &mut e,
        "isequal(a.Rules,b.Rules) && isequal(b.Rules,c.Rules) && isequal(a.Rules(3).Antecedent,[3 -2]) && a.Rules(2).Weight==0.5 && a.Rules(1).Connection==2",
    );
    for format in ["symbolic", "verbose", "indexed"] {
        run(
            &mut e,
            &format!("txt=showrule(a,Format='{format}');d=addRule(f,txt);"),
        );
        check(&mut e, "isequal(a.Rules,d.Rules)");
    }
    run(
        &mut e,
        "rules=fisrule({'service==poor | food==rancid => tip=cheap','service==excellent & food~=delicious => tip=generous'});",
    );
}
#[test]
fn fisrule_constructor_and_rule_property_edits() {
    let mut e = Engine::default();
    run(&mut e, TIPP);
    run(
        &mut e,
        "r=fisrule('If service is poor or food is not rancid then tip is cheap (0.5)');",
    );
    check(
        &mut e,
        "isempty(r.Antecedent) && isempty(r.Consequent) && r.Weight==0.5 && r.Connection==2",
    );
    run(
        &mut e,
        "a=addRule(f,r);q=fisrule([1 -1 1 0.5 2],2);b=addRule(f,q);",
    );
    check(&mut e, "isequal(a.Rules,b.Rules)");
    run(
        &mut e,
        "a.Rules(1).Weight=0.75;a.Rules(1).Connection=1;a.Rules(1).Antecedent=[2 -2];",
    );
    check(
        &mut e,
        "a.Rules(1).Weight==0.75 && a.Rules(1).Connection==1 && isequal(a.Rules(1).Antecedent,[2 -2])",
    );
    run(&mut e, "r.Weight=0.25;r.Connection=1;");
    check(
        &mut e,
        "contains(r.Description,'(0.25)') && contains(r.Description,' & ')",
    );
    run(&mut e, "a.Rules=[];");
    check(
        &mut e,
        "isempty(a.Rules) && strcmp(class(a.Rules),'fisrule')",
    );
}
#[test]
fn rule_description_edits_resolve_against_fis_variables() {
    let mut e = Engine::default();
    run(
        &mut e,
        "f=mamfis(NumInputs=1,NumInputMFs=1,NumOutputs=1,NumOutputMFs=1,AddRules='none');f=addMF(f,'input1','trimf',[0 .5 1]);f=addMF(f,'output1','trimf',[0 .5 1]);f=addRule(f,'input1==mf1 => output1=mf1');f.Rules(1).Description='input1==mf2 => output1=mf2';",
    );
    check(
        &mut e,
        "isequal(f.Rules(1).Antecedent,2) && isequal(f.Rules(1).Consequent,2) && contains(f.Rules(1).Description,'mf2')",
    );
    fails(
        &mut e,
        "f.Rules(1).Description='input1==missing => output1=mf2'",
        "Unknown membership",
    );
    check(
        &mut e,
        "isequal(f.Rules(1).Antecedent,2) && isequal(f.Rules(1).Consequent,2)",
    );
}
#[test]
fn editing_removes_references_and_shifts_signed_indices() {
    let mut e = Engine::default();
    run(&mut e, TIPP);
    run(
        &mut e,
        "f=addRule(f,[1 1 1 1 2;2 0 2 1 1;3 -2 -3 1 1]);g=removeMF(f,'service','good');",
    );
    check(
        &mut e,
        "numel(g.Rules)==2 && isequal(g.Rules(2).Antecedent,[2 -2]) && isequal(g.Rules(2).Consequent,-3)",
    );
    run(&mut e, "h=removeInput(f,'service');");
    check(
        &mut e,
        "numel(h.Inputs)==1 && numel(h.Rules)==2 && isequal(h.Rules(2).Antecedent,-2)",
    );
    run(&mut e, "h=removeMF(f,'tip','average');");
    check(&mut e, "numel(h.Rules)==2 && h.Rules(2).Consequent==-2");
    run(
        &mut e,
        "h=addOutput(f,[0 1],Name='other',NumMFs=2);h=addRule(h,[1 1 0 2 1 1]);h=removeOutput(h,'tip');",
    );
    check(
        &mut e,
        "numel(h.Outputs)==1 && numel(h.Rules)==1 && h.Rules(1).Consequent==2",
    );
    run(
        &mut e,
        "v=addMF(fisvar,'gaussmf',[1 0],Name='normal');w=removeMF(v,'normal');",
    );
    check(
        &mut e,
        "numel(v.MembershipFunctions)==1 && isempty(w.MembershipFunctions)",
    );
    check(&mut e, "numel(f.Inputs)==2 && numel(f.Rules)==3");
}
